"""Prepare a non-final CAS configuration from closed subsets; no engine import, ZIP or life writes."""
import argparse, ast, hashlib, json
from pathlib import Path

def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):
    if p.exists(): raise FileExistsError(str(p))
    p.write_text(json.dumps(v,ensure_ascii=False,sort_keys=True,indent=2)+'\n',encoding='utf8')
def main():
    ap=argparse.ArgumentParser(description=__doc__)
    ap.add_argument('--lab',type=Path,required=True)
    ap.add_argument('--system',type=Path,required=True)
    a=ap.parse_args()
    close=a.lab/'cierre'
    previous=close/'CONFIG_ANALISIS_PREPARACION_APD01_R01.json'
    cfg=json.loads(previous.read_text(encoding='utf8'))
    cfg['status']='PREPARACION_NO_FINAL'
    cfg['configuration_revision']='R02_with_executed_references; service/final documents explicitly pending'
    cfg['previous_configuration_sha256']=sha(previous)
    refs=close/'REFERENCIAS_EJECUTADAS_APD01_R2'
    cfg['stages'].append({'namespace':'REFERENCIAS_EJECUTADAS','source':str(refs),'manifest':'MANIFIESTO.json','plan':'PLAN_RECALCULO.json'})
    cfg['candidate_stage_slots']=[
      {'namespace':'SERVICIO_APD01','source':str(close/'SERVICIO_APD01_R01'),'manifest':'MANIFIESTO.json','plan':'PLAN_RECALCULO.json','expected_jobs':7,'status':'WAIT_FOR_DELIVERY_CLOSED_NOTICE_AND_EXACT_BYTES','scope':'Includes interrupted R01, pilot and final reached R02 without concealing technical failures. This placeholder is not an assembled stage.'},
      {'namespace':'DELTA_OPERATIVO','status':'WAIT_FOR_ROOT_FROZEN_SYSTEM_AND_FINAL_METADATA','scope':'Analysis code/contract delta only; no engine, wheel or dense native snapshot. Not an independent continuation package.'},
      {'namespace':'PRUEBA_PAQUETE_EXACTO','status':'WAIT_FOR_ROOT_FINAL_GO_AND_EXACT_PACKAGE_BYTES','scope':'Final extraction/recalculation proof is outside the package self-reference; do not claim performed now.'}
    ]
    cfg['candidate_public_file_slots']=[
      {'id':'INFORME_CIENTIFICO','to':'INFORME_CIENTIFICO.md','source':None,'status':'WAIT_FOR_ROOT_EXACT_FINAL_DOCUMENT_BYTES'},
      {'id':'MANUAL_WORD','to':'MANUAL_MAESTRO_APD01.docx','source':None,'status':'WAIT_FOR_ROOT_EXACT_FINAL_WORD_AND_RENDER_SCOPE'},
      {'id':'CONTINUIDAD','to':'CONTINUIDAD_ASISTENTE_APD01.json','source':None,'status':'WAIT_FOR_ROOT_REAL_FINAL_SAVED_CUT_AND_PAIR'},
      {'id':'CAPACIDADES_POR_VIDA','to':'CAPACIDADES_POR_VIDA.json','source':None,'status':'WAIT_FOR_ROOT_FINAL_PHYSICAL_VS_OPERATIONAL_COVERAGE'},
      {'id':'INCORPORACIONES','to':'INCORPORACIONES.md','source':None,'status':'WAIT_FOR_ROOT_CLOSED_CONTRACT_AND_GUIDE'}
    ]
    cfg['public_files']=[]
    cfg['pending_components']=[
      {'id':'SERVICIO_RESERVADO_UNA_HORA','status':'WAIT_FOR_FINAL_STOP_AND_CLOSED_STAGE','scope':'No final service verdict or final tick presumed. Interrupted R01 and surviving queued work must remain identifiable.'},
      {'id':'MANUAL_MAESTRO_WORD','status':'WAIT_FOR_ROOT_FINAL_DOCUMENT_BYTES','scope':'Only received final Word bytes, not this configuration, can represent the updated manual.'},
      {'id':'INFORME_CIENTIFICO_ROOT_Y_CONTINUIDAD','status':'WAIT_FOR_EXACT_FINAL_SAVED_CUT','scope':'Final physical state, paired protocol and limitations must come from the actual reached life.'},
      {'id':'DELTA_OPERATIVO_FINAL','status':'WAIT_FOR_CLOSED_SOURCE_CONTRACTS_AND_FROZEN_ACTOR','scope':'Selected actual system-layer sources and metadata; never motor, WHL or all dense states.'},
      {'id':'PRUEBA_PAQUETE_FINAL_EXACTO','status':'WAIT_FOR_GO_AND_PACKAGE_BYTES','scope':'No ZIP or final proof is generated by this preparation.'}
    ]
    checks=[]
    for entry in cfg['stages']:
        root=Path(entry['source']);mp=root/entry['manifest'];m=json.loads(mp.read_text(encoding='utf8'))
        expected={row.get('file',row.get('path')):row for row in m['members']}
        actual={p.relative_to(root).as_posix():p for p in root.rglob('*') if p.is_file() and p!=mp}
        if set(actual)!=set(expected): raise ValueError('Closed stage membership differs: '+entry['namespace'])
        for name,p in actual.items():
            row=expected[name]
            if p.stat().st_size!=row['bytes'] or sha(p)!=row['sha256']: raise ValueError('Closed source bytes differ: '+name)
        subplan=json.loads((root/entry['plan']).read_text(encoding='utf8'))
        jobs=subplan.get('cases',subplan.get('jobs'))
        if not isinstance(jobs,list): raise ValueError('Unsupported stage plan')
        checks.append({'namespace':entry['namespace'],'manifest_sha256':sha(mp),'files':len(actual)+1,'bytes':sum(p.stat().st_size for p in actual.values())+mp.stat().st_size,'planned_recalculations':len(jobs)+len(entry.get('extra_cases',[]))})
    apd_paths=['capacidades/asistente_proposito_01.py','capacidades/aritmetica_apd_01.py','capacidades/acumulador_adquirido_apd_01.py','capacidades/lexico_apd_01.py','capacidades/lexico_apd_extendido_02.py','capacidades/lexico_apd_extendido_04.py','capacidades/ruta_adquirida_apd_03.py']
    transports=['gestionar.py','app/cola_local.py','app/servicio_persistente.py']
    shared=['app/native_tools.py','capacidades/mente_unificada_01.py','capacidades/mente_acumulativa_r02.py','capacidades/percepcion_cruda_fi01.py','capacidades/selector_acrecion_nativo.py']
    rows=[]
    for group,paths in [('APD_OPERATIONAL_MODULES',apd_paths),('AFFECTED_TRANSPORT_OR_ENTRY',transports),('PREEXISTING_LOCAL_DEPENDENCY_NOT_NEW_ACQUISITION',shared)]:
        for name in paths:
            p=a.system/name
            if not p.is_file():raise FileNotFoundError(str(p))
            ast.parse(p.read_text(encoding='utf-8-sig'),filename=name)
            rows.append({'relative_system_path':name,'group':group,'bytes_observed':p.stat().st_size,'sha256_observed_not_final_freeze':sha(p),'final_selection_status':'WAIT_FOR_ROOT_FREEZE_CONFIRMATION','analysis_target':'DELTA_OPERATIVO/sistema/'+name})
    plan={'schema':'APD01.system_delta_candidate.v1','status':'PREPARACION_NO_FINAL','native_ticks':0,'source_system_local_locator':str(a.system),'files_observed':rows,'pending_metadata_paths':['contratos/ASISTENTE_PROPOSITO_01.json','documentacion/GUIA_ASISTENTE_APD01.md','capacidades/CATALOGO_CAPACIDADES.json'],'pending_metadata_paths_are_proposals_not_asserted_present':True,'exclude':['engine','official wheel','dense snapshots','journals/outbox as scientific response memory','credentials','unrelated campaign history'],'scope':'This is a selected source-layer delta for analysis, not a complete installable platform or a replacement for full-state paired continuation packages. Do not copy these observed bytes over later root edits without confirming final freeze.'}
    write(close/'CONFIG_ANALISIS_CANDIDATA_APD01_R02.json',cfg)
    write(close/'PLAN_DELTA_CANDIDATO_APD01_R01.json',plan)
    write(close/'VALIDACION_CONFIG_CANDIDATA_APD01_R02.json',{'native_ticks':0,'new_ZIP':False,'closed_stage_checks':checks,'planned_cases_before_service':sum(x['planned_recalculations'] for x in checks),'expected_additional_service_cases':7,'public_files_waiting':len(cfg['candidate_public_file_slots']),'candidate_delta_python_files_AST_valid':len(rows),'final_stage_copied_or_assembled':False})
    print(json.dumps({'closed_stages':len(checks),'cases':sum(x['planned_recalculations']for x in checks),'delta_source_candidates':len(rows),'status':'PREPARACION_NO_FINAL','native_ticks':0}))
if __name__=='__main__':main()

